CREATE TABLE IF NOT EXISTS rm_workspace_user_access_events (
  id INTEGER PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES "user"(id) CHECK(length(trim(user_id)) > 0),
  event_type TEXT NOT NULL CHECK(event_type IN ('activate', 'disable')),
  workspace_role TEXT CHECK(workspace_role IN ('workspace_owner', 'member')),
  actor TEXT NOT NULL CHECK(length(trim(actor)) > 0),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CHECK(
    (event_type = 'activate' AND workspace_role IN ('workspace_owner', 'member'))
    OR (event_type = 'disable' AND workspace_role IS NULL)
  )
);

CREATE INDEX IF NOT EXISTS rm_workspace_user_access_events_current_idx
  ON rm_workspace_user_access_events(user_id, id DESC);

CREATE TABLE IF NOT EXISTS rm_company_membership_events (
  id INTEGER PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES "user"(id) CHECK(length(trim(user_id)) > 0),
  company_slug TEXT NOT NULL CHECK(length(trim(company_slug)) > 0),
  event_type TEXT NOT NULL CHECK(event_type IN ('grant', 'revoke')),
  company_role TEXT CHECK(company_role IN ('owner', 'bookkeeper', 'reviewer', 'reader')),
  actor TEXT NOT NULL CHECK(length(trim(actor)) > 0),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CHECK(
    (event_type = 'grant' AND company_role IN ('owner', 'bookkeeper', 'reviewer', 'reader'))
    OR (event_type = 'revoke' AND company_role IS NULL)
  )
);

CREATE INDEX IF NOT EXISTS rm_company_membership_events_current_idx
  ON rm_company_membership_events(user_id, company_slug, id DESC);

CREATE TABLE IF NOT EXISTS rm_workspace_security_events (
  id INTEGER PRIMARY KEY,
  scope TEXT NOT NULL CHECK(scope IN ('workspace', 'user')),
  user_id TEXT REFERENCES "user"(id),
  event_type TEXT NOT NULL CHECK(event_type = 'session_invalidate'),
  actor TEXT NOT NULL CHECK(length(trim(actor)) > 0),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CHECK((scope = 'workspace' AND user_id IS NULL) OR (scope = 'user' AND length(trim(user_id)) > 0))
);

CREATE INDEX IF NOT EXISTS rm_workspace_security_events_current_idx
  ON rm_workspace_security_events(scope, user_id, id DESC);

CREATE TRIGGER IF NOT EXISTS rm_workspace_user_access_events_no_update
BEFORE UPDATE ON rm_workspace_user_access_events
BEGIN
  SELECT RAISE(ABORT, 'workspace user access events are append-only');
END;

CREATE TRIGGER IF NOT EXISTS rm_workspace_user_access_events_no_delete
BEFORE DELETE ON rm_workspace_user_access_events
BEGIN
  SELECT RAISE(ABORT, 'workspace user access events are append-only');
END;

CREATE TRIGGER IF NOT EXISTS rm_company_membership_events_no_update
BEFORE UPDATE ON rm_company_membership_events
BEGIN
  SELECT RAISE(ABORT, 'company membership events are append-only');
END;

CREATE TRIGGER IF NOT EXISTS rm_company_membership_events_no_delete
BEFORE DELETE ON rm_company_membership_events
BEGIN
  SELECT RAISE(ABORT, 'company membership events are append-only');
END;

CREATE TRIGGER IF NOT EXISTS rm_workspace_security_events_no_update
BEFORE UPDATE ON rm_workspace_security_events
BEGIN
  SELECT RAISE(ABORT, 'workspace security events are append-only');
END;

CREATE TRIGGER IF NOT EXISTS rm_workspace_security_events_no_delete
BEFORE DELETE ON rm_workspace_security_events
BEGIN
  SELECT RAISE(ABORT, 'workspace security events are append-only');
END;
